sys_script_include.script:
var IDCLogger = Class.create();
IDCLogger.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    idcLogger: function() {
		// Method to log the entries into our custom log table
        var logLevel = this.getParameter("sysparm_logLevel");
        var script = this.getParameter("sysparm_script");
        var message = this.getParameter("sysparm_message");
        var log = new GlideRecordSecure('x_1784056_sixscape_log');
        log.initialize();
        log.log_level = logLevel;
        log.script = script;
        log.application = "Sixscape IDC";
        log.message = message;
        log.insert();
    },
    type: 'IDCLogger'
});
